//#region src/test-utils/helpers.ts
const text = (content, marks) => ({
	type: "text",
	text: content,
	...marks && { marks }
});
const linkMark = (href, options = {}) => ({
	type: "link",
	attrs: {
		href,
		linktype: options.linktype ?? "url",
		target: options.target ?? null,
		anchor: options.anchor ?? null,
		uuid: options.uuid ?? null,
		custom: options.custom ?? void 0
	}
});
const tableCell = (content, attrs = {}, marks) => ({
	type: "tableCell",
	content: [{
		type: "paragraph",
		content: [text(content, marks)]
	}],
	attrs: {
		colspan: attrs.colspan ?? 1,
		rowspan: attrs.rowspan ?? 1,
		...attrs.colwidth && { colwidth: attrs.colwidth },
		...attrs.backgroundColor && { backgroundColor: attrs.backgroundColor }
	}
});
const tableHeader = (content, marks) => ({
	type: "tableHeader",
	content: [{
		type: "paragraph",
		content: [text(content, marks)]
	}],
	attrs: {
		colspan: 1,
		rowspan: 1
	}
});
const tableRow = (cells) => ({
	type: "tableRow",
	content: cells
});
const table = (rows) => ({
	type: "table",
	content: rows
});
const doc = (content) => ({
	type: "doc",
	content: Array.isArray(content) ? content : [content]
});
